def _find_path(self, label):
    if self.label == label:
        return [self]

    for child in self.children:
        sub = child._find_path(label)
        if sub is not None:
            return [self] + sub

    return None

def from_pov(self, from_node):
    path = self._find_path(from_node)
    if path is None:
        raise ValueError("Tree could not be reoriented")

    # Rebuild bottom-up: the target node becomes the root, and each
    # ancestor on the path becomes a child of the node below it.
    result = Tree(path[-1].label, [c for c in path[-1].children])
    for i in range(len(path) - 2, -1, -1):
        node = path[i]
        rest = [c for c in node.children if c is not path[i + 1]]
        result = Tree(node.label, rest + [result])
    return result

